def check(log,source):
    matches=re.findall(r'^%Warning-([A-Z0-9_]+): ([^:\n]+):(\d+):(\d+): (.*)$',log,re.M)
    if len(matches)!=len(re.findall(r'^%Warning-',log,re.M)):
        raise ValueError('Unparsed compiler warning')
    allowed={(r['code'],r['file'],r['source_line_sha256'],r['message']):r['maximum_count'] for r in ROWS}
    observed=collections.Counter()
    for code,file,line,column,message in matches:
        text=(source/file).read_text().splitlines()[int(line)-1]
        key=(code,file,hashlib.sha256(text.encode()).hexdigest(),message)
        observed[key]+=1
        if key not in allowed or observed[key]>allowed[key]:
            raise ValueError('Unreviewed compiler warning '+code+' '+file+':'+line+' '+message)
    return {'total':len(matches),'by_code':dict(collections.Counter(r[0] for r in matches)),
            'all_warning_identities_and_counts_within_reviewed_source_bound_policy':True}
